/** National median hourly wage for janitors (BLS, May 2024) */
export const NATIONAL_MEDIAN_WAGE = 17.27;

/** Get market data for a city by its slug */
export function getCityMarketData(slug: string, stateCode: string) {
    const msaCode = CITY_MSA_MAP[slug];
    const metro = msaCode ? METRO_DATA[msaCode] : undefined;
    const state = STATE_DATA[stateCode];
    const population = CITY_POPULATIONS[slug];
    const fips = STATE_FIPS[stateCode];

    return {
        population,
        metro,
        state,
        fips,
        /** Link to Census data for this state */
        censusUrl: fips ? DATA_SOURCES.census.stateUrl(fips) : DATA_SOURCES.census.baseUrl,
        /** Link to BLS wage data */
        blsUrl: DATA_SOURCES.bls.url,
        /** How this metro compares to national median */
        wageVsNational: metro
            ? Math.round(((metro.medianWage - NATIONAL_MEDIAN_WAGE) / NATIONAL_MEDIAN_WAGE) * 100)
            : undefined,
    };
}
